/** Routes that must never be indexed, and so are kept out of the sitemap. */
export const DISALLOWED_PATHS = ['/404', '/500'];

/**
 * Real pages that must not be indexed, so they are absent from the sitemap but
 * still get a prerendered HTML file carrying `noindex, follow`. They need their
 * own file: without one they fall through to the 404 handler and report a false
 * missing-page status for a page that genuinely exists.
 *
 * NOINDEX_PATHS is derived from PAGE_SEO's `noindex` flag in src/config/seo.js,
 * which owns the title and description. It is intentionally not re-exported
 * here — see the note on the one-way dependency above.
 */

/** Join SITE_URL and a route path into an absolute URL, no double slashes. */
export function absoluteUrl(path = '/') {
  if (/^https?:\/\//i.test(path)) return path;
  const suffix = path.startsWith('/') ? path : `/${path}`;
  return `${SITE_URL}${suffix === '/' ? '/' : suffix.replace(/\/+$/, '')}`;
}

/** Turn a sitemap `src` into an absolute URL for an <image:loc> entry. */
export function absoluteAssetUrl(src) {
  return absoluteUrl(src.startsWith('/') ? src : `/${src}`);
}
